<?php
declare(strict_types=1);
require __DIR__.'/db.php';
$pdo=db();
try {
  $pdo->exec("ALTER TABLE products ADD COLUMN brand VARCHAR(80) NULL AFTER name");
} catch (PDOException $e) { if ((int)($e->errorInfo[1]??0)!==1060) throw $e; }
try { $pdo->exec("CREATE TABLE IF NOT EXISTS deals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, discount_type ENUM('percentage','fixed') NOT NULL, discount_value DECIMAL(10,2) NOT NULL, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_deals_active_dates(is_active,start_at,end_at), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB"); } catch(Throwable $e){throw $e;}
$categories=['Laptops'=>1,'Mobile Phones'=>2,'Headphones'=>3,'Cameras'=>4,'Accessories'=>5];
$brands=['Samsung','Apple','Dell','HP','Lenovo','ASUS','Acer','Sony','JBL','Canon','Nikon','Logitech','Xiaomi','Anker','Garmin'];
$prefix=['Laptops'=>['ProBook','ThinkPad','ZenBook','Aspire','Inspiron','MacBook','Galaxy Book','Pavilion','ROG Strix','Swift'],'Mobile Phones'=>['Galaxy','iPhone','Redmi','Pixel','OnePlus','Xperia','Nokia','Zenfone','Poco','Moto'],'Headphones'=>['WH','QuietComfort','Tune','AirPods','Soundcore','Momentum','Crusher','Live','Studio','Elite'],'Cameras'=>['EOS','Alpha','Z','Lumix','PowerShot','Coolpix','X-T','OM-D','Cyber-shot','GoPro'],'Accessories'=>['USB-C Hub','Power Bank','Smart Watch','Wireless Mouse','Mechanical Keyboard','Tablet','Docking Station','Webcam','SSD','Router']];
$prices=['Laptops'=>[159000,589000],'Mobile Phones'=>[34900,489000],'Headphones'=>[12900,149000],'Cameras'=>[39900,549000],'Accessories'=>[7900,129000]];
$find=$pdo->prepare('SELECT id FROM products WHERE name=?');$insert=$pdo->prepare('INSERT INTO products(category_id,brand,name,description,price,stock,image,featured,active) VALUES(?,?,?,?,?,?,?,?,1)');
foreach($categories as $cat=>$cid){$count=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE category_id=".(int)$cid." AND active=1")->fetchColumn();for($i=$count;$i<30;$i++){ $brand=$brands[($cid*7+$i)%count($brands)];$name=$brand.' '.$prefix[$cat][$i%count($prefix[$cat])].' '.(2024+($i%3)).' '.str_pad((string)($i+1),2,'0',STR_PAD_LEFT);$find->execute([$name]);if($find->fetch())continue;$range=$prices[$cat];$price=$range[0]+(($i*7919+$cid*3137)%($range[1]-$range[0]));$image=['Laptops'=>'laptop.svg','Mobile Phones'=>'phone.svg','Headphones'=>'headphones.svg','Cameras'=>'camera.svg','Accessories'=>'tablet.svg'][$cat];$insert->execute([$cid,$brand,$name,$brand.' '.$cat.' with reliable performance for Sri Lankan customers.',$price,10+(($i*7)%55),$image,$i<4?1:0]);}}
$dealProducts=$pdo->query('SELECT id FROM products WHERE active=1 ORDER BY id LIMIT 12')->fetchAll(PDO::FETCH_COLUMN);$deal=$pdo->prepare('INSERT INTO deals(product_id,discount_type,discount_value,start_at,end_at,is_active) VALUES(?,?,?,?,?,1)');$pdo->exec('DELETE FROM deals WHERE product_id IN ('.implode(',',array_map('intval',$dealProducts)).')');$start=(new DateTime('now',new DateTimeZone('Asia/Colombo')))->format('Y-m-d H:i:s');$end=(new DateTime('+14 days',new DateTimeZone('Asia/Colombo')))->format('Y-m-d H:i:s');foreach($dealProducts as $i=>$pid){$deal->execute([(int)$pid,$i%3===0?'fixed':'percentage',$i%3===0?5000:10+($i%4)*5,$start,$end]);}
echo "Catalog seeded to 30 per category and 12 active deals.\n";
